// Build a safe error record. Credentials and payload bodies are never copied out.
//
// v2 adds ONE thing: a pre-escaped `telegram_text` field, so the Telegram node
// can send with an explicit parse_mode of HTML instead of relying on whatever
// mode applies when parse_mode is absent.
//
// WHY. Execution 263 proved a parse mode IS applied today: a message containing
// six backticks came back from Telegram with the backticks stripped and three
// `code` entities at the matching offsets. Execution 233 proved the same mode
// silently ate a "[line 1]" - it was delivered as "line 1". That is legacy
// Markdown. It means a single unpaired _ * or ` in an n8n error message returns
// HTTP 400 "can't parse entities", and this node is the last line of defence.
//
// It also means the "[redacted]" marker this very node inserts is being eaten
// before the owner sees it, so a redacted credential currently reads as though
// nothing was redacted.
//
// HTML needs only three characters escaped and has no balance requirement, so
// every error string survives verbatim. That is also the house convention: all
// eleven Telegram nodes in workflow 4 set parse_mode HTML explicitly.
//
// EVERY EXISTING FIELD IS UNCHANGED. The Events register mapping reads
// event_id, event_type, severity, matter_id, action_id, workflow_name,
// workflow_id, node, message, execution_id, execution_url and created_at. All
// twelve are produced exactly as before, from the same inputs, unescaped. Only
// the new telegram_text field is escaped, and only the Telegram node reads it.
const j = $input.first().json || {};
const ex = j.execution || {};
const wfd = j.workflow || {};
const tr = j.trigger || {};

// ---------------------------------------------------------------------------
// REDACTION v3. Redacts secret VALUES; it no longer deletes whole lines.
//
// THE DEFECT THIS REPLACES. v2 dropped any line matching the word token,
// secret, password, authorization, bearer, cookie or api key. That is a
// keyword test, not a secret test, so it deleted ordinary technical errors:
// "Unexpected token '<' ... is not valid JSON" - one of the most common
// JavaScript errors there is - was blanked entirely, and the owner received
// "Error:" with nothing after it. A one-line message mentioning any of those
// words vanished completely.
//
// It also protected less than it appeared to. The line drop only fires when a
// LABEL is present; a bare secret with no label was never covered by it, and
// was only ever caught by the 32-character run rule.
//
// THE REPLACEMENT. Five value-shaped rules, then the original run rule, in
// this order. Header values are redacted to end of line because the whole
// value of an Authorization or Cookie header is sensitive. Assignment values
// are redacted one token at a time so the surrounding sentence survives.
// Nothing is deleted by line any more.
const BOT_TOKEN   = /\b\d{5,16}:[A-Za-z0-9_-]{20,}/g;
const BOT_IN_URL  = /\/bot[A-Za-z0-9_:-]{20,}/gi;
const HEADER_LABEL = /\b(authorization|proxy-authorization|www-authenticate|set-cookie|cookie|x-api-key)(\s*[:=]\s*)[^\n]+/gi;
const SCHEME_VALUE = /\b(bearer|basic|digest)\s+[A-Za-z0-9._~+/=-]{8,}/gi;
const ASSIGN_LABEL = /\b(api[-_ ]?keys?|apikeys?|access[-_ ]?tokens?|refresh[-_ ]?tokens?|auth[-_ ]?tokens?|bot[-_ ]?tokens?|id[-_ ]?tokens?|client[-_ ]?secrets?|private[-_ ]?keys?|secrets?|passwords?|passwd|pwd|passphrase|session[-_ ]?ids?|credentials?|bearer|tokens?)(\s*[:=]+\s*)("[^"]*"|'[^']*'|[^\s,;)\]}]+)/gi;

// ---------------------------------------------------------------------------
// toText v5 — FU-3, allowlist extraction. NOT a serialiser.
//
// THE DEFECT. safe() began with String(s), so a non-string message became
// "[object Object]" in the Events register and the daily digest showed the owner
// "workflow / node: [object Object]". Every fact was lost.
//
// WHY NOT FLATTEN. The obvious fix - walk the object and print every leaf - was
// built, tested and REJECTED. An n8n error payload can carry a whole node
// definition, and that object contains `credentials: {id, name}`, request and
// response bodies, headers and internal configuration. Flattening turns a field
// that leaked nothing into one that writes all of it to a spreadsheet. Redaction
// would have caught the obvious secrets, but "the redactor will probably catch
// it" is not a boundary.
//
// WHAT THIS DOES INSTEAD. It never traverses. It looks for a human-readable
// error string in an explicit allowlist of fields, and if it does not find one
// it says so and stops. Unknown keys are not read. Denied containers are not
// read at any depth. Arrays are not flattened. Nothing is inferred.
//
//   ALLOWED:   message, description, name, code, status, statusCode,
//              httpCode, type          (scalars only - never objects)
//   CONTAINERS: error, cause, details  (descended into, allowlist only)
//   EVERYTHING ELSE: not read. node, credentials, context, headers, request,
//              response, config, body, data, token, secret, password,
//              authorization, cookies and every unknown key are unreachable
//              because they are not on the allowlist, not because they are on
//              a denylist. A denylist would need to predict the next key name;
//              this cannot be widened by a payload it has not seen.
//
// Whatever single string comes out then passes through the six redaction rules
// exactly as a string message does.
const SAFE_FIELDS = ['message', 'description', 'name', 'code', 'status',
                     'statusCode', 'httpCode', 'type'];
const ERROR_CONTAINERS = ['error', 'cause', 'details'];
const TOTEXT_MAX_DEPTH = 3;
const TOTEXT_MAX_ARRAY_SCAN = 5;

// Realm-safe: a Code node runs inside a vm, so instanceof fails on anything
// built in another realm. The internal tag does not.
function typeTag(v) {
  const t = Object.prototype.toString.call(v);
  return t.slice(8, -1);
}

// A getter can throw. Reading a key must never take the workflow down.
function readKey(o, k) { try { return o[k]; } catch (e) { return undefined; } }

// Scalars only. An allowlisted field holding an OBJECT is ignored, not
// stringified and not descended into - that is how a `name` or `type` key
// nested inside a credentials blob stays unreachable.
function scalarText(v) {
  if (v === null || v === undefined) return null;
  const k = typeof v;
  if (k === 'string') return v.trim() === '' ? null : v;
  if (k === 'number') return Number.isFinite(v) ? String(v) : null;
  if (k === 'bigint' || k === 'boolean') return String(v);
  return null;
}

function extractSafe(v, depth, seen) {
  if (v === null || typeof v !== 'object') return null;
  if (depth > TOTEXT_MAX_DEPTH) return null;
  if (seen.indexOf(v) !== -1) return null;          // cycle: stop, do not throw
  seen.push(v);
  try {
    if (typeTag(v) === 'Array') {
      // Arrays are never flattened. Only a directly allowlisted error OBJECT
      // inside one may contribute; loose strings and numbers do not.
      let len = 0;
      try { len = v.length >>> 0; } catch (e) { len = 0; }
      const scan = len < TOTEXT_MAX_ARRAY_SCAN ? len : TOTEXT_MAX_ARRAY_SCAN;
      for (let i = 0; i < scan; i++) {
        const el = readKey(v, i);
        if (el && typeof el === 'object' && typeTag(el) !== 'Array') {
          const got = extractSafe(el, depth + 1, seen);
          if (got) return got;
        }
      }
      return null;
    }
    for (let i = 0; i < SAFE_FIELDS.length; i++) {
      const s = scalarText(readKey(v, SAFE_FIELDS[i]));
      if (s) return s;
    }
    for (let j = 0; j < ERROR_CONTAINERS.length; j++) {
      const c = readKey(v, ERROR_CONTAINERS[j]);
      // A container that is a STRING is not read. In execution 244 `cause` held
      // a raw n8n expression full of markup; that is not an error message.
      if (c && typeof c === 'object') {
        const got = extractSafe(c, depth + 1, seen);
        if (got) return got;
      }
    }
    return null;
  } catch (e) {
    return null;
  } finally {
    seen.pop();
  }
}

function omitted(tag, extra) {
  return '[non-string error payload omitted; type=' + tag + (extra || '') + ']';
}

function toText(input) {
  // A string is returned untouched, so string messages stay byte-identical.
  if (typeof input === 'string') return input;
  if (input === null || input === undefined) return '';

  const prim = typeof input;
  if (prim === 'number' || prim === 'boolean' || prim === 'bigint') return String(input);
  if (prim === 'symbol') return omitted('Symbol');
  if (prim === 'function') return omitted('Function');

  let tag;
  try { tag = typeTag(input); } catch (e) { tag = 'Object'; }

  if (tag === 'Date') {
    try { return isNaN(input.getTime()) ? omitted('Date', ', invalid') : input.toISOString(); }
    catch (e) { return omitted('Date', ', unreadable'); }
  }
  if (tag === 'Error') {
    let nm = '', ms = '';
    try { nm = scalarText(input.name) || ''; } catch (e) { nm = ''; }
    try { ms = scalarText(input.message) || ''; } catch (e) { ms = ''; }
    if (nm || ms) return (nm ? nm + (ms ? ': ' : '') : '') + ms;
    return omitted('Error');
  }

  let found = null;
  try { found = extractSafe(input, 0, []); } catch (e) { found = null; }
  if (found) return found;

  if (tag === 'Array') {
    let len = 0;
    try { len = input.length >>> 0; } catch (e) { len = 0; }
    return omitted('Array', ', length=' + len);
  }
  return omitted(tag);
}

function safe(s, max) {
  let t = toText(s);

  // 1. Telegram bot token, digits colon opaque run.
  t = t.replace(BOT_TOKEN, '[redacted]');
  // 2. The same token embedded in an api.telegram.org path.
  t = t.replace(BOT_IN_URL, '/bot[redacted]');
  // 3. Header-style: the entire value is the secret.
  t = t.replace(HEADER_LABEL, function (m, label, sep) { return label + sep + '[redacted]'; });
  // 4. Bare scheme plus credential, with no label in front of it.
  t = t.replace(SCHEME_VALUE, function (m, scheme) { return scheme + ' [redacted]'; });
  // 5. Assignment-style: redact the value, keep the sentence. A value shorter
  //    than three characters is left alone so that prose like "token = in"
  //    is not mangled; anything that short is not a credential worth hiding
  //    behind a label, and rule 6 still covers long opaque runs.
  //    Bare "token" and "bearer" ARE in the label list, but only ever fire
  //    with a colon or equals after them, so "Unexpected token '<'" and
  //    "missing token in expression" are untouched while "token=abc123" is not.
  t = t.replace(ASSIGN_LABEL, function (m, label, sep, value) {
    const bare = value.replace(/^["']|["']$/g, '');
    return bare.length < 3 ? m : label + sep + '[redacted]';
  });
  // 6. UNCHANGED from v1 and v2: any long opaque run, labelled or not.
  t = t.replace(/[A-Za-z0-9_\-]{32,}/g, '[redacted]');

  return t.slice(0, max || 600);
}

// Telegram HTML mode. Ampersand first, or the escapes escape each other.
function esc(s) {
  return String(s === undefined || s === null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const lastNode = String(ex.lastNodeExecuted || tr.error && tr.error.node || 'unknown');
const message = safe((ex.error && (ex.error.message || ex.error.description)) || (tr.error && tr.error.message) || 'No message', 500);

// Pull matter and action ids out of the failing item if they are present.
let matterId = '', actionId = '';
try {
  const blob = JSON.stringify(ex.error || {}) + ' ' + JSON.stringify(j.data || {});
  const m = blob.match(/\b(MAT-[A-Za-z0-9-]+)\b/);
  const a = blob.match(/\b(ACT-[A-Za-z0-9-]+)\b/);
  if (m) matterId = m[1];
  if (a) actionId = a[1];
} catch (e) {}

const workflowName = String(wfd.name || 'unknown');
const executionId = String(ex.id || '');
const hasAction = !!actionId;

// The FAILED claim is now conditional. Mark Action Failed only runs when
// has_action is true, and in all seven recorded WF9 executions it never ran -
// yet every delivered message still claimed the action had been set to FAILED.
const closing = hasAction
  ? 'I set the action to FAILED. A retry will not duplicate a send.'
  : 'No action id was identified, so no action status was changed.';

const telegram_text = [
  'A workflow run failed.',
  '',
  'Workflow: ' + esc(workflowName),
  'Node: ' + esc(lastNode),
  'Matter: ' + (matterId ? esc(matterId) : 'not identified'),
  'Action: ' + (actionId ? esc(actionId) : 'not identified'),
  'Error: ' + esc(message),
  'Execution: ' + esc(executionId),
  '',
  'The failed run sent nothing outside this chat.',
  closing,
].join('\n');

return [{ json: {
  event_id: 'EVT-' + new Date().toISOString().replace(/[^0-9]/g, '').slice(0, 14),
  event_type: 'WORKFLOW_FAILED',
  severity: 'ERROR',
  matter_id: matterId,
  action_id: actionId,
  workflow_name: workflowName,
  workflow_id: String(wfd.id || ''),
  node: lastNode,
  message,
  execution_id: executionId,
  execution_url: String(ex.url || ''),
  mode: String(ex.mode || ''),
  created_at: new Date().toISOString(),
  has_action: hasAction,
  telegram_text: telegram_text,
}}];
